# Native user-mode decoder acceptance, using generated sine and solid-color samples.
import base64, io, struct, wave
import _infinity_media as codec
buf=io.BytesIO()
with wave.open(buf, "wb") as wav:
    wav.setparams((1,2,16000,0,"NONE",""))
    wav.writeframes(struct.pack("<hh",1200,-1200)*800)
samples=[buf.getvalue()]
samples.append(base64.b64decode(b''))
samples.append(base64.b64decode(b''))
for sample in samples:
    audio, duration=codec.open(sample,0,48000)
    assert duration > 0
    frames=[]
    while True:
        frame=codec.next(audio)
        if frame is None: break
        frames.append(frame[1])
    pcm=b''.join(frames)
    assert len(pcm)>=4000 and any(pcm) and len(pcm)%4==0
    codec.seek(audio,0)
    assert codec.next(audio) is not None
assert codec.open(samples[1],1,48000) is None
video,duration=codec.open(samples[2],1,48000)
pts,pixels=codec.next(video)
header,extent,peak,rgb=pixels.split(b'\n',3)
assert header==b'P6' and extent==b'32 32' and len(rgb)==32*32*3
assert rgb[0]>200 and rgb[1]<20 and rgb[2]<20
try:
    codec.open(b'invalid',0,48000)
except ValueError: pass
else: raise AssertionError('invalid container accepted')
